def months_until(current, growth_pct, capacity, max_util_pct):
    threshold = capacity * max_util_pct / 100
    if current > threshold:
        return 0
    if growth_pct <= 0:
        return None
    m, load = 0, current
    while load <= threshold:
        m += 1
        load = current * (1 + growth_pct / 100) ** m
    return m

