coding.solution:
import statistics

def regressions(baseline, current, tolerance_pct):
    out = []
    for name, runs in baseline.items():
        if name not in current:
            out.append(f'{name} (missing)')
            continue
        limit = max(runs) * (1 + tolerance_pct / 100)
        if statistics.median(current[name]) > limit:
            out.append(name)
    return sorted(out)
